const languageColumn: Record<AppLanguage, number> = {
  English: -1,
  Hindi: 0,
  Spanish: 1,
  French: 2,
  Mandarin: 3,
  Arabic: 4
};

export function translate(text: string, language: AppLanguage): string {
  const column = languageColumn[language];
  return column < 0 ? text : rows[text]?.[column] ?? text;
}
